const originalTopicCount=g8AllTopics().length;
for(const [index,[raw,[parent,title]]] of Object.entries(newTopics).entries()){
 const base=g8InfoById('g8:'+parent);
 const group=G8_GROUPS.find(item=>item.topics.includes(base));
 const chapter=chapters.find(chapter=>chapter.items.some(([, ,ids])=>ids.includes(raw)));
 const source=base.course==='algebra'?'Макарычев и др., 2024':base.course==='geometry'?'Атанасян и др., 2023':
  'Высоцкий и Ященко, 2023, часть '+(['VII','VIII','IX'].includes(chapter.chapter)?1:2);
 const section=chapter.title;
 const topic={...base,id:'g8:'+raw,title,shortTitle:title,section,source,textbookRef:source,order:originalTopicCount+index+1,rendererType:'quiz',plannedRendererType:'quiz'};
 group.topics.push(topic);
}
const catalogAudit=g8CatalogAudit;
g8CatalogAudit=function(){
 const report=catalogAudit(),topics=g8AllTopics(),ids=new Set(topics.map(topic=>topic.id)),orders=new Set(topics.map(topic=>topic.order));
 const issues=report.issues.filter(issue=>issue!=='count'&&issue!=='order');
 if(ids.size!==originalTopicCount+Object.keys(newTopics).length)issues.push('count');
 const linked=chapters.flatMap(({items})=>items.flatMap(([, ,rawIds])=>rawIds.map(raw=>'g8:'+raw)));
 if(chapters.some(({items})=>items.some(([, ,rawIds])=>!rawIds.length))||linked.some(id=>!ids.has(id))||new Set(linked).size!==ids.size)issues.push('textbook-links');
 if(orders.size!==topics.length||topics.some(topic=>topic.order<1||topic.order>topics.length))issues.push('order');
 return {...report,issues,ok:issues.length===0};
};

g8Lesson=function(id){
 const lesson=newTopics[rawCourseId(id)]?.[2];
 return lesson?'<div class="g6-theory"><h3>Правило</h3>'+(lesson.startsWith('<p>')?lesson:'<p>'+lesson+'</p>')+'</div>':previousLesson(id);
};
const algebraReviewMasters={
 real_numbers_compare:{
  compareAfterTranslation:()=>{
   const a=ri(3,10),shift=ri(2,6),delta=g8Pick([-2,-1,1,2]),n=a*a+delta;
   return choice(`Сравни √${n} + ${shift} и ${a+shift}. Какой знак сравнения верен?`,delta>0?'>':'&lt;',
    [delta>0?'&lt;':'>','='],`Вычитаем ${shift} из обеих частей. При сравнении √${n} и ${a} можно сравнить их квадраты ${n} и ${a*a}.`);
  },
  countRationalsAfterSimplifying:()=>{
   const a=ri(2,6),b=ri(2,7),m=g8Pick([2,3,5,7]),n=g8Pick([2,3,5,7]);
   const items=[`√${a*a}`,`√${b*b*m} − ${b}√${m}`,`√${b*b*m} + √${n}`,frac(a,b),`√${m*n}`];
   return number(`Сколько рациональных чисел в списке ${items.join('; ')}? Считай каждую запись отдельно.`,m===n?4:3,
    `Первые два числа равны ${a} и 0. Четвёртое число — дробь из целых. Третья запись — сумма положительных кратных √${m} и √${n}. При равных подкоренных множителях это одно кратное иррационального корня, а при разных квадрат суммы содержит иррациональное слагаемое. Последний корень рационален только при ${m} = ${n}.`);
  },
  chooseBetweenNegativeRadicals:()=>{
   const a=ri(3,11),d=ri(2,7);
   return number(`Найди наибольшее целое k, при котором дробь ${frac('k',d)} строго между −√${(a+1)**2+1} и −√${a*a+1}.`,
    Math.ceil(-d*Math.sqrt(a*a+1))-1,
    `Умножаем обе границы на ${d}. Нужен последний целый k строго левее −${d}√${a*a+1}, который остаётся правее левой границы.`);
  },
  countIntegersAfterTranslation:()=>{
   const a=ri(3,12),steps=ri(2,6),shift=ri(2,9),b=a+steps;
   return number(`Сколько целых чисел лежит строго между ${shift} − √${b*b+2} и ${shift} − √${a*a-1}?`,steps+1,
    `Сравнивая квадраты, получаем ${b} &lt; √${b*b+2} &lt; ${b+1} и ${a-1} &lt; √${a*a-1} &lt; ${a}. Подходят целые числа от ${integer(shift-b)} до ${integer(shift-a)} включительно.`);
  },
  locateMedian:()=>{
   const a=ri(4,10),m=g8Pick([2,3,5,7]);
   const rows=[{text:`−√${(a-1)**2*m}`,rank:2},{text:`−${a}√${m}`,rank:0},
    {text:`−√${a*a*m-1}`,rank:1},{text:`√${m}`,rank:3},{text:`√${4*m}`,rank:4}];
   const order=shuffleOptions(rows.slice());
   const correct=order.findIndex(row=>row.rank===2)+1;
   return number(`Какое число окажется третьим, если записать пять чисел по возрастанию? Укажи его номер в списке.<br>${order.map((row,i)=>'№'+(i+1)+' — '+row.text).join('; ')}.`,correct,
    `Первыми идут три отрицательных числа. Наибольшим из них будет −√${(a-1)**2*m}, поскольку модуль этого числа наименьший.`);
  },
  restoreRationalSum:()=>{
   const a=ri(2,8),b=ri(2,7),m=g8Pick([2,3,5,7]);
   return number(`При каком целом k значение выражения √${a*a*m} + k√${m} + ${b} рационально?`,-a,
    `Выносим ${a} из первого корня. Получаем (${a} + k)√${m} + ${b}. Корень иррационален, поэтому ${a} + k = 0.`);
  },
  compareProductsExactly:()=>{
   const a=ri(4,12),delta=g8Pick([-2,-1,1,2]),n=a*a+delta;
   return choice(`Какой знак подходит в записи √(${n} · ${a*a+1}) □ ${a}√${a*a+1}?`,delta>0?'>':'&lt;',
    [delta>0?'&lt;':'>','='],
    `Делим обе части на положительный корень √${a*a+1}. Остаётся сравнить √${n} и ${a} по квадратам.`);
  },
  irrationalQuotients:()=>{
   const a=ri(2,8),m=g8Pick([2,3,5,7]),n=g8Pick([2,3,5,7]);
   const first=frac(`√${a*a*m}`,`√${m}`),second=frac(`√${m*n}`,`√${m}`),third=frac(`√${a*a*n}`,`√${m}`);
   return number(`Сколько частных в списке ${first}; ${second}; ${third} иррациональны?`,m===n?1:2,
    `Первое частное равно ${a}, второе равно √${n}. Третье равно ${a}√(${n}/${m}). Оно рационально при одинаковых простых числах ${n} и ${m}.`);
  },
  distanceFromInteger:()=>{
   const a=ri(4,12),d=ri(2,4),n=(a*d)**2+g8Pick([-1,1]);
   const before=n<(a*d)**2;
   return choice(`По какую сторону от ${a} на числовой прямой находится ${frac(`√${n}`,d)} и меньше ли расстояние до ${a}, чем ${frac(1,d)}?`,
    before?'Слева, расстояние меньше':'Справа, расстояние меньше',
    [before?'Справа, расстояние меньше':'Слева, расстояние меньше','Слева, расстояние не меньше','Справа, расстояние не меньше'],
    `Число ${n} лежит строго между (${a*d-1})² и (${a*d+1})², а сравнение с ${(a*d)**2} определяет сторону.`);
  },
  betweenShiftedRadicals:()=>{
   const a=ri(4,12),b=a+ri(2,7),shift=ri(2,6),list=[a*a-1,a*a+1,b*b-1,b*b+1];
   return number(`Сколько из чисел ${list.map(n=>`√${n} − ${shift}`).join('; ')} попадают в открытый промежуток (${integer(a-shift)}; ${b-shift})?`,2,
    `К каждой границе прибавляем ${shift} и сравниваем квадраты с ${a*a} и ${b*b}. Подходят подкоренные числа ${a*a+1} и ${b*b-1}.`);
  }
 },
 irrational_numbers_approximations:{
  countRadicandsAfterRounding:()=>{
   const a=ri(8,22);
   return number(`Сколько целых n дают √n, который при округлении до целых равен ${a}?`,2*a,
    `Корень должен быть от ${a-0.5} включительно до ${a+0.5} исключительно. Возводим границы в квадрат и берём целые n от ${a*a-a+1} до ${a*a+a}.`);
  },
  locateUsingHundredths:()=>{
   const a=ri(110,270),left=(a/100).toFixed(2).replace('.',','),right=((a+1)/100).toFixed(2).replace('.',',');
   return number(`Известно, что ${left} &lt; √(${frac('n',10000)}) &lt; ${right}. Найди наименьшее целое n.`,a*a+1,
    `Обе границы положительны. Возводим их в квадрат и умножаем на 10 000. Тогда n строго между ${a*a} и ${(a+1)**2}.`);
  },
  roundingNegativeRoot:()=>{
   const a=ri(3,12),n=a*a+ri(1,2*a);
   return number(`Округли −√${n} до десятых.`,rational(-Math.round(Math.sqrt(n)*10),10),
    `Сравниваем √${n} с серединами между соседними десятыми. Округляем его модуль, затем возвращаем знак минус.`);
  },
  selectGuaranteedSquareRange:()=>{
   const a=ri(12,29),left=rationalRu(rational(a,10)),right=rationalRu(rational(a+1,10));
   const low=rationalRu(rational(a*a,100)),up=rationalRu(rational((a+1)**2,100));
   return choice(`Известно, что ${left} ≤ √n &lt; ${right}. Какая запись точно передаёт границы для n?`,
    `${low} ≤ n &lt; ${up}`,[`${low} &lt; n ≤ ${up}`,`${left} ≤ n &lt; ${right}`,`${low} ≤ n ≤ ${up}`],
    `Возводим обе неотрицательные границы в квадрат. Нижняя граница остаётся включённой, верхняя исключённой.`);
  },
  errorFromTwoBounds:()=>{
   const a=ri(12,35),width=ri(1,4),low=rationalRu(rational(a,10)),up=rationalRu(rational(a+width,10));
   const mid=rationalRu(rational(2*a+width,20)),error=rational(width,20);
   return number(`Значение корня лежит между ${low} и ${up}. Для приближения взяли середину ${mid}. Какова верхняя граница абсолютной погрешности приближения?`,error,
    `Расстояние от середины до каждой границы равно половине ширины промежутка: (${up} − ${low}) : 2 = ${rationalRu(error)}.`);
  },
  scaledRootRounding:()=>{
   const a=ri(3,10),n=a*a+ri(1,2*a),scale=ri(2,5);
   return number(`Вычисли с точностью до десятых значение ${scale}√${n}. Сначала учти множитель ${scale}, затем округли.`,
    rational(Math.round(10*Math.sqrt(n*scale*scale)),10),
    `Вносим множитель под знак корня и получаем √${n*scale*scale}. Округляем значение этого корня до десятых.`);
  },
  minimumBlankLength:()=>{
   const a=ri(3,9),n=a*a+ri(1,2*a);
   return number(`Сторона квадратной детали площадью ${n} см² равна √${n} см. Какова минимальная длина заготовки в миллиметрах, если длина заготовки — целое число и она должна быть не меньше стороны?`,
    Math.ceil(Math.sqrt(100*n)),
    `Сторона в миллиметрах равна √${100*n}. Выбираем ближайшее целое сверху, чтобы длины хватило.`,'мм');
  },
  adaptBoundAfterDivision:()=>{
   const a=ri(4,13),k=ri(2,6),n=(a*k)**2+ri(1,k*k-1);
   return number(`Найди наибольшее целое число, которое не превосходит ${frac(`√${n}`,k)}.`,a,
    `Квадраты ${a*k} и ${(a+1)*k} дают ${(a*k)**2} &lt; ${n} &lt; ${((a+1)*k)**2}. Извлекаем корни, делим на ${k} и получаем границы ${a} и ${a+1}.`);
  },
  roundingThreshold:()=>{
   const a=ri(21,79),target=rationalRu(rational(a,100),2);
   const lower=(2*a-1)**2,upper=(2*a+1)**2;
   return number(`Число √(${frac('n',40000)}) при округлении до сотых даёт ${target}. Если значение ровно посередине, округляй вверх. Найди наибольшее целое n.`,upper-1,
    `Для округления берём половину сотой слева и справа. После возведения этих границ в квадрат и умножения на 40 000 получаем ${lower} ≤ n &lt; ${upper}.`);
  },
  compareEstimatesOnBothSides:()=>{
   const a=ri(3,12),n=a*a+a;
   return choice(`Ученик оценил √${n} числом ${a}, а его одноклассник — числом ${a+1}. Какая оценка ближе?`,String(a),
    [String(a+1),'Оценки одинаково точны'],
    `Середина между оценками равна ${a},5. Квадрат середины равен ${n},25, он больше ${n}. Поэтому корень находится левее середины.`);
  }
 },
 algebra_grade8_review:{
  fractionalEquationAfterFactoring:()=>{
   const a=ri(2,8),x=a+ri(1,6),c=a+x;
   return number(`Реши уравнение ${frac(`x² − ${a*a}`,`x − ${a}`)} = ${c} при условии x ≠ ${a}. Найди x.`,x,
    `Разлагаем числитель как (x − ${a})(x + ${a}). Дробь равна x + ${a} при x ≠ ${a}. Отсюда x = ${c} − ${a} = ${x}.`);
  },
  countRootsAfterCancelling:()=>{
   const a=ri(3,13);
   return number(`Сколько решений у уравнения ${frac(`x² − ${a*a}`,`x − ${a}`)} = x + ${a}, если x — целое число от −${a} до ${a} включительно?`,2*a,
    `Равенство верно для каждого допустимого x, потому что числитель раскладывается на (x − ${a})(x + ${a}). Из ${2*a+1} целых исключаем x = ${a}.`);
  },
  quadraticAndInequality:()=>{
   const a=ri(3,10),b=a+ri(2,8);
   return number(`Реши уравнение x² − ${a+b}x + ${a*b} = 0. Какой корень удовлетворяет неравенству 2x &gt; ${a+b}?`,b,
    `По теореме Виета корни ${a} и ${b}. Неравенство требует, чтобы x был больше среднего корней, поэтому подходит только ${b}.`);
  },
  inverseProportionAndLine:()=>{
   const a=ri(2,6),b=a+ri(2,7);
   return number(`Графики y = ${frac(a*b,'x')} и y = x + ${b-a} пересекаются при двух значениях x. Найди положительную абсциссу точки пересечения.`,a,
    `Приравниваем функции и умножаем на x ≠ 0. Получаем x² + ${b-a}x − ${a*b} = 0. Разложение (x − ${a})(x + ${b}) даёт положительный корень ${a}.`);
  },
  systemAndRoot:()=>{
   const a=ri(4,9),b=ri(2,a-1);
   return number(`Числа x и y удовлетворяют системе x + y = ${a*a+b*b} и x − y = ${integer(a*a-b*b)}. Вычисли √x + √y.`,a+b,
    `Складываем уравнения и получаем 2x = ${2*a*a}. Вычитание даёт 2y = ${2*b*b}. Следовательно, √x = ${a} и √y = ${b}.`);
  },
  exponentAndInequality:()=>{
   const n=ri(3,7),m=ri(2,5);
   return number(`Найди наименьшее целое x, для которого ${g8Pow82(2,'x')} · ${g8Pow82(2,-n)} &gt; ${g8Pow82(4,m)}.`,2*m+n+1,
    `Справа ${g8Pow82(2,2*m)}, слева показатель x − ${n}. При основании 2 > 1 неравенство равносильно x − ${n} > ${2*m}.`);
  },
  conjugatesAndCancellation:()=>{
   const a=ri(3,12),b=ri(2,a-1),m=g8Pick([2,3,5,7]);
   return number(`Упрости выражение ${frac(`(√${a*a*m} − ${b}√${m})(√${a*a*m} + ${b}√${m})`,m)}. Найди его значение.`,a*a-b*b,
    `Числитель — произведение суммы и разности. Получаем ${a*a*m} − ${b*b*m}, затем делим на ${m}.`);
  },
  functionDomainAndInequality:()=>{
   const a=ri(2,7),b=a+ri(2,6);
   return number(`Сколько целых x от 0 до ${b+2} включительно одновременно входят в область определения функции y = ${frac(1,`√(${b} − x)`)} и удовлетворяют неравенству x ≥ ${a}?`,b-a,
    `Выражение под корнем в знаменателе должно быть строго положительным. Получаем x &lt; ${b}. Остаются целые x от ${a} до ${b-1}.`);
  },
  vietaSquareDifference:()=>{
   const a=ri(3,10),b=a+ri(2,7);
   return number(`У уравнения x² − ${a+b}x + ${a*b} = 0 два корня. Найди квадрат разности корней, пользуясь их суммой и произведением.`,(b-a)**2,
    `По теореме Виета сумма равна ${a+b}, произведение равно ${a*b}. Применяем (x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂.`);
  },
  scientificNotationAndSquare:()=>{
   const a=ri(2,9),k=ri(2,5),n=a*a;
   const coefficient=n>=10?rationalRu(rational(n,10)):String(n),exponent=2*k+(n>=10?1:0);
   return number(`В уравнении x² = ${coefficient} · ${g8Pow82(10,exponent)} найди положительный корень и запиши его в стандартном виде. Укажи показатель при основании 10.`,k,
    `Число справа можно записать как ${n} · ${g8Pow82(10,2*k)}. Положительный корень равен ${a} · ${g8Pow82(10,k)}, где ${a} — коэффициент стандартного вида.`);
  }
 }
};

function functionGraph(task,curves=[],marks=[]){
 const values=curves.flat().concat(marks);
 const range=Math.max(5,...values.flatMap(([x,y])=>[Math.abs(x),Math.abs(y)]));
 const series=curves.map((curve,i)=>({
  points:curve.map(([x,y])=>({x:rational(x),y:rational(y)})),
  label:curves.length===1?'График функции':i===0?'График f':'График g',
  alt:i>0
 }));
 const points=marks.map(([x,y,label])=>g7PointOnLine(x,0,y,label));
 const graphCaption=curves.length?'График на координатной плоскости':'Отмеченные пары на координатной плоскости';
 return {...task,graph:g7GraphData(series,{range,points,caption:graphCaption}),graphCaption};
}
function valuesTable(task,headers,rows){
 return {...task,table:{headers,rows}};
}
function modulusCurve(h,k,radius,scale=1){
 return [[h-radius,k+scale*radius],[h,k],[h+radius,k+scale*radius]];
}
function shiftedTerm(variable,shift){
 if(shift===0)return variable;
 return variable+(shift>0?' + ':' − ')+Math.abs(shift);
}
function linearRule(slope,offset){
 return shiftedTerm(({1:'x','-1':'−x'})[slope]??integer(slope)+'x',offset);
}

const functionMasters={
 absolute_value_function:{
  inverseLevelSpan:()=>{
   const h=ri(-2,2),k=ri(-2,1),d=ri(2,4);
   return functionGraph(number(`На рисунке показан график y = f(x). Найди разность большего и меньшего x, для которых f(x) = ${k+d}.`,
    2*d,`Горизонталь y = ${k+d} пересекает ветви при x = ${integer(h-d)} и x = ${integer(h+d)}. Разность равна ${2*d}.`),
    [modulusCurve(h,k,d+1)]);
  },
  axisBeforeValue:()=>{
   const h=g8Pick([-2,-1,1,2]),k=ri(-2,1),dx=g8Pick([-2,-1,1,2]),x=h+dx;
   return functionGraph(number(`На рисунке показан график y = f(x). Абсцисса одной точки равна ${integer(x)}. Найди абсциссу второй точки с той же ординатой.`,
    h-dx,`Ось симметрии проходит через вершину x = ${integer(h)}. Вторая абсцисса отстоит от неё на ${Math.abs(dx)} в другую сторону.`),
    [modulusCurve(h,k,4)]);
  },
  intersectionWithLine:()=>{
   const h=ri(-1,1),k=ri(-2,1),d=ri(1,2),left=h-d;
   
   return functionGraph(number('На рисунке показаны V-образный график и прямая. Найди сумму координат их единственной общей точки.',
    left+k+d,`На графике точка пересечения имеет координаты (${integer(left)}; ${integer(k+d)}). Складываем абсциссу и ординату.`),
    [modulusCurve(h,k,3),[[left-1,k+d-2],[left+1,k+d+2]]]);
  },
  compareUnevenBranches:()=>{
   const h=ri(-2,2),k=ri(-1,2),d=ri(1,2),extra=ri(1,2),left=h-d,right=h+d+extra;
   return functionGraph(number(`На сколько значение функции при x = ${integer(right)} больше её значения при x = ${integer(left)}? Используй график.`,extra,
    `Ординаты на ветвях равны ${k+d+extra} и ${k+d}. Вычитаем меньшее из большего.`),
    [modulusCurve(h,k,4)]);
  },
  identifyCoefficientFromGraph:()=>{
   const h=ri(-2,2),k=ri(-2,1),a=ri(2,3),direction=g8Pick([-1,1]),x=h+direction*2,y=k+2*a;
   return functionGraph(number(`График задаётся формулой y = a·|${shiftedTerm('x',-h)}|${shiftedTerm('',k)}. По точке A и вершине найди a.`,a,
    `У точки A абсцисса ${integer(x)} и ордината ${integer(y)}. От вершины до неё 2 единицы по горизонтали и ${2*a} по вертикали. Делим ${2*a} на 2.`),
    [modulusCurve(h,k,2,a)],[[x,y,'A']]);
  },
  countVisibleIntegerInputs:()=>{
   const h=ri(-2,2),k=ri(-2,1),d=ri(2,4);
   return functionGraph(number(`Сколько целых x на показанном участке графика удовлетворяют f(x) &lt; ${k+d}?`,
    2*d-1,`Горизонталь y = ${k+d} пересекает график при x = ${integer(h-d)} и x = ${integer(h+d)}. Берём только целые числа строго между ними.`),
    [modulusCurve(h,k,d+1)]);
  },
  shiftedModulusMinimum:()=>{
   const h=ri(-3,3),k=ri(-3,3),d=ri(1,3),direction=g8Pick([-1,1]);
   const lo=direction>0?h+d:h-d-3,hi=direction>0?h+d+3:h-d;
   return number(`Какое наименьшее значение принимает y = ${shiftedTerm('|'+shiftedTerm('x',-h)+'|',k)} на отрезке [${integer(lo)}; ${integer(hi)}]?`,k+d,
    `Вершина находится при x = ${integer(h)} вне отрезка. Ближайший к ней конец отрезка отстоит на ${d}, поэтому минимум равен ${integer(k)} + ${d} = ${integer(k+d)}.`);
  },
  distanceBetweenRoots:()=>{
   const h=ri(-4,4),k=ri(2,5),d=ri(2,4);
   return number(`Найди расстояние на координатной прямой между решениями уравнения |${shiftedTerm('x',-h)}| − ${k} = ${d}.`,2*(k+d),
    `Каждый корень отстоит от ${integer(h)} на ${k+d}. Они лежат по разные стороны, поэтому расстояние между ними равно ${2*(k+d)}.`);
  },
  relateTwoVertices:()=>{
   const h=g8Pick([-2,-1,1,2]),k=ri(-2,1),delta=ri(1,3),g=h+delta;
   return functionGraph(number('У двух V-образных графиков вершины лежат на одной горизонтали. На сколько единиц нужно передвинуть левый график вправо, чтобы вершины совпали?',
    delta,`Абсциссы вершин равны ${integer(h)} и ${integer(g)}. Сдвиг вправо равен разности этих абсцисс, то есть ${delta}.`),
    [modulusCurve(h,k,3),modulusCurve(g,k,3)]);
  },
  sumOfIntercepts:()=>{
   const h=ri(-2,2),k=ri(2,4);
   return functionGraph(number('График пересекает ось Ox в двух точках. Найди сумму абсцисс этих точек.',
    2*h,`Точки пересечения имеют ординату 0 и расположены симметрично относительно x = ${integer(h)}. Их абсциссы ${integer(h-k)} и ${integer(h+k)}.`),
    [modulusCurve(h,-k,k+1)]);
  }
 },
 function_concept:{
  repairOutputForRepeatedInput:()=>{
   const a=ri(2,8),b=ri(-5,5),c=ri(1,4);
   return valuesTable(number('В таблице перечислены пары аргумента и значения одной функции. Какое число нужно написать вместо вопросительного знака?',b,
    `Аргумент ${a} встречается дважды. Оба раза значение должно совпадать и равняться ${integer(b)}.`),
    ['x','y'],[[a,b],[a+1,b+c],[a+2,b-c],[a,'?']]);
  },
  removeFewestPairs:()=>{
   const a=ri(2,7),b=ri(1,6),c=ri(2,3),d=ri(2,3);
   const rows=[...Array.from({length:c},(_,i)=>[a,b+i]),...Array.from({length:d},(_,i)=>[a+1,b-i]),[a+2,b]];
   return valuesTable(number('Какое наименьшее число строк надо убрать, чтобы оставшиеся пары задавали функцию?',c+d-2,
    `У аргумента ${a} можно оставить одну из ${c} строк. У аргумента ${a+1} можно оставить одну из ${d}. Строку с аргументом ${a+2} сохраняем.`),
    ['x','y'],shuffleOptions(rows));
  },
  applyRuleTwiceFromTable:()=>{
   const a=ri(-3,3),b=a+ri(1,3),c=b+ri(1,3);
   return valuesTable(number(`Таблица задаёт функцию f. Сначала найди f(${integer(a)}), затем используй найденное значение как аргумент той же функции. Какой результат получишь?`,c,
    `Из строки с x = ${integer(a)} получаем ${integer(b)}. Из строки с x = ${integer(b)} получаем ${integer(c)}.`),
    ['x','f(x)'],shuffleOptions([[a,b],[b,c],[c,a]]));
  },
  detectGraphConflict:()=>{
   const a=g8Pick([-3,-2,-1,1,2,3]),b=ri(-2,1);
   return functionGraph(number('На рисунке отмечены пары (x; y). При каком x эти пары нарушают условие, что функция задаёт только одно значение y?',
    a,`Две точки с абсциссой ${integer(a)} имеют разные ординаты: ${integer(b)} и ${integer(b+3)}. Остальные абсциссы встречаются по одному разу.`),
    [],[[a-2,b+1,'A'],[a,b,'B'],[a,b+3,'C'],[a+2,b-1,'D']]);
  },
  distinguishRepeatedOutputs:()=>{
   const a=ri(2,7),y=ri(-4,4);
   return choice(`Известно, что f(${a}) = f(${a+2}) = ${integer(y)}. Какое утверждение верно?`,
    'Два разных аргумента могут иметь одно значение функции',
    ['Если значения совпали, зависимость перестала быть функцией','Значение этой функции одинаково для всех аргументов','При каждом из указанных аргументов значение функции может быть любым'],
    'Определение требует единственного значения для каждого конкретного аргумента. Значения при разных аргументах могут совпадать.');
  },
  joinRulesAtBoundary:()=>{
   const a=ri(2,7),k=ri(2,4),b=ri(1,4),t=g8Pick([2,3,4,5].filter(slope=>slope!==k));
   return number(`При x ≤ ${a} действует правило y = ${linearRule(k,b)}, а при x ≥ ${a} — правило y = ${t}x + c. Найди c, при котором оба правила вместе задают функцию.`,
    (k-t)*a+b,`Области двух правил перекрываются только при x = ${a}. Приравниваем значения ${k*a+b} и ${t*a} + c в этой точке.`);
  },
  compositionDistinguishOrder:()=>{
   const a=ri(2,6),b=ri(1,4),c=-ri(1,3);
   return number(`Даны f(x) = ${linearRule(2,b)} и g(x) = ${linearRule(1,c)}. Вычисли f(g(${a})) − g(f(${a})).`,c,
    `Сначала считаем внутренние значения. Получаем f(g(${a})) = ${integer(2*(a+c)+b)}, а g(f(${a})) = ${integer(2*a+b+c)}. Вычитаем в заданном порядке.`);
  },
  matchInputOfTwoRecords:()=>{
   const a=ri(2,8),b=ri(-4,4),c=b+ri(2,4);
   const rows=[[a,b],[a+1,b],[a+2,c],[a+3,c]];
   return valuesTable(choice('Какую пару можно добавить в таблицу и по-прежнему получить функцию?',
    `(${a+4}; ${integer(b)})`,[`(${a}; ${integer(c)})`,`(${a+2}; ${integer(b)})`,`(${a+1}; ${integer(c)})`],
    `Аргумент ${a+4} новый. Остальные пары присваивают уже использованному аргументу второе значение.`),['x','y'],rows);
  },
  countInputsForSharedOutput:()=>{
   const a=ri(-4,-2),y=ri(-3,3),count=ri(2,4);
   const rows=Array.from({length:5},(_,i)=>[a+i,i<count?y:y+i+1]);
   return valuesTable(number(`При скольких различных аргументах функция имеет значение ${integer(y)}?`,count,
    `Выбираем строки с f(x) = ${integer(y)} и считаем их аргументы. Совпадение выходов допустимо.`),
    ['x','f(x)'],shuffleOptions(rows));
  },
  noRuleForAnInput:()=>{
   const a=ri(2,7),step=ri(2,4);
   return number(`На вход можно подать любое целое x от ${a} до ${a+4} включительно. Первое правило задаёт y = x + ${step} только при x ≤ ${a+1}, второе задаёт y = x − ${step} только при x ≥ ${a+3}. Какой аргумент остался без значения?`,
    a+2,`Левое правило заканчивается на ${a+1}, а правое начинается с ${a+3}. Число ${a+2} не входит ни в одну часть.`);
  }
 },
 function_representations:{
  readMissingTableCell:()=>{
   const m=g8Pick([-2,-1,1,2]),b=ri(-2,2),a=g8Pick([-2,-1,1,2]),value=m*a+b;
   return functionGraph(number(`График соответствует таблице, в которой указаны x = ${integer(a)} и пустая ячейка f(x). Какое число нужно вписать в эту ячейку?`,
    value,`Проводим вертикаль через x = ${integer(a)} до графика. Считываем ординату ${integer(value)}.`),
    [[[-3,b-3*m],[3,b+3*m]]]);
  },
  restoreCoefficientFromTable:()=>{
   const m=g8Pick([-3,-2,-1,1,2,3]),b=ri(-3,3),a=ri(-2,1),d=ri(2,3);
   return valuesTable(number('Таблица задаёт линейную функцию y = kx + b. Найди k по изменению аргумента и значения.',m,
    `Аргумент меняется на ${d}, значение меняется на ${integer(m*d)}. Делим изменение значения на изменение аргумента.`),
    ['x','y'],[[a,m*a+b],[a+d,m*(a+d)+b],[a+2*d,m*(a+2*d)+b]]);
  },
  restoreInterceptFromGraph:()=>{
   const m=g8Pick([-2,-1,1,2]),b=ri(-3,3),x=ri(1,3);
   return functionGraph(number(`Точка A лежит на графике y = ${linearRule(m,0)} + b. Используя её координаты, найди b.`,
    b,`Подставляем координаты точки A в формулу: ${integer(m*x+b)} = ${m} · ${x} + b. Отсюда b = ${integer(b)}.`),
    [[[-2,b-2*m],[3,b+3*m]]],[[x,m*x+b,'A']]);
  },
  matchTableToFormula:()=>{
   const a=ri(1,3),b=ri(-3,3),d=ri(1,3),start=ri(-3,-2);
   const f=x=>a*x+b;
   return valuesTable(choice('Выбери линейную формулу, которой соответствуют все строки таблицы.',
    `y = ${linearRule(a,b)}`,[`y = ${linearRule(a+d,b)}`,`y = ${linearRule(a,b+d)}`,`y = ${linearRule(-a,b)}`],
    `На 1 вправо значение меняется на ${a}. При x = 0 читаем y = ${integer(b)}. Поэтому y = ${linearRule(a,b)}.`),
    ['x','y'],[[start,f(start)],[start+1,f(start+1)],[0,b]]);
  },
  correctMismatchedTable:()=>{
   const k=g8Pick([-3,-2,-1,1,2,3]),b=ri(-4,4),count=ri(1,3);
   const inputs=[-2,-1,0,1,2],errors=shuffleOptions(inputs.slice()).slice(0,count);
   const rows=inputs.map(x=>[x,k*x+b+(errors.includes(x)?ri(1,4):0)]);
   return valuesTable(number(`Сколько строк таблицы надо исправить, чтобы она соответствовала формуле y = ${linearRule(k,b)}?`,
    count,`Сравниваем каждое табличное y с ${linearRule(k,b)}. Расхождения при x = ${valueList(errors.slice().sort((a,b)=>a-b))}.`),
    ['x','y'],rows);
  },
  combineFormulaWithGraph:()=>{
   const k=g8Pick([-2,-1,1,2]),b=ri(-2,2),a=g8Pick([-2,-1,1,2]),offset=ri(1,4),value=k*a+b;
   return functionGraph(number(`Графиком задана f. Формулой задана g(x) = f(x) + ${offset}. Найди g(${integer(a)}).`,
    value+offset,`С графика читаем f(${integer(a)}) = ${integer(value)}. Прибавляем ${offset} и получаем ${integer(value+offset)}.`),
    [[[-3,b-3*k],[3,b+3*k]]]);
  },
  recoverLinearStepFromGraph:()=>{
   const k=g8Pick([-2,-1,1,2]),b=ri(-2,2),a=ri(-2,0),d=ri(2,3);
   const y=k*a+b,next=k*(a+d)+b;
   return functionGraph(number('По точкам A и B найди скорость изменения функции — на сколько меняется y при увеличении x на 1.',
    k,`От A до B абсцисса увеличилась на ${d}, ордината изменилась на ${integer(next-y)}. Делим ${integer(next-y)} на ${d}.`),
    [[[-3,b-3*k],[3,b+3*k]]],[[a,y,'A'],[a+d,next,'B']]);
  },
  retrieveInputFromWordRule:()=>{
   const b=ri(15,30),k=ri(3,7),t=ri(3,8);
   return valuesTable(number(`В баке было ${b} л воды. Каждую минуту добавляют по ${k} л. Объём воды через t минут обозначили как V(t). Какое t пропущено в таблице?`,t,
    `Правило задаёт V(t) = ${b} + ${k}t. Вычитаем начальный объём из ${b+k*t} и делим прирост на ${k}.`,'мин'),
    ['t, мин','V(t), л'],[[0,b],[1,b+k],['?',b+k*t]]);
  },
  applyShiftToTable:()=>{
   const a=ri(-3,0),b=ri(1,5),step=g8Pick([-2,-1,1,2]);
   const rows=[[a,b],[a+1,b+step],[a+2,b+2*step],[a+3,b+3*step]];
   return valuesTable(number(`Таблица задаёт f. Чтобы получить g, к каждому значению f прибавили ${Math.abs(step)}. Найди g(${integer(a+2)}) по таблице.`,
    b+2*step+Math.abs(step),`При x = ${integer(a+2)} в таблице стоит ${integer(b+2*step)}. Прибавляем ${Math.abs(step)}.`),
    ['x','f(x)'],shuffleOptions(rows));
  },
  twoGraphsSameArgument:()=>{
   const h=ri(-2,1),a=h+ri(1,2),b=ri(-2,1),g=ri(-2,2),y=b+a-h;
   return functionGraph(number(`На рисунке V-образный график задаёт f, горизонтальный — g. Вычисли f(${integer(a)}) − g(${integer(a)}).`,
    y-g,`При x = ${integer(a)} ординаты графиков равны ${integer(y)} и ${integer(g)}. Вычитаем в указанном порядке.`),
    [modulusCurve(h,b,3),[[h-3,g],[h+3,g]]]);
  }
 },
 function_domain_range:{
  integerDomainTwoRestrictions:()=>{
   const a=ri(-4,0),b=a+ri(4,8),c=ri(a,b);
   return number(`Сколько целых x входят в область определения функции y = ${frac('√('+shiftedTerm('x',-a)+') · √('+shiftedTerm('−x',b)+')',shiftedTerm('x',-c))}?`,b-a,
    `Два корня дают ограничения x ≥ ${integer(a)} и x ≤ ${b}. В отрезке ${b-a+1} целых чисел, но x = ${integer(c)} обращает знаменатель в нуль.`);
  },
  rangeFromNonMonotoneGraph:()=>{
   const low=ri(-3,-1),high=ri(2,4),middle=ri(0,1),shift=ri(-1,1);
   const curve=[[-4+shift,middle],[-2+shift,low],[shift,middle],[2+shift,high],[4+shift,middle]];
   const answer=`[${integer(low)}; ${high}]`;
   return functionGraph(choice('На рисунке показан весь график функции. Укажи её множество значений.',answer,
    [`[${integer(-4+shift)}; ${4+shift}]`,`(${integer(low)}; ${high})`,`[${middle}; ${high}]`],
    `Множество значений читаем по оси Oy. Нижняя точка имеет y = ${integer(low)}, верхняя y = ${high}. Между ними график проходит непрерывно.`),
    [curve]);
  },
  compareDomainAndRangeLengths:()=>{
   const h=ri(-3,-1),d=ri(3,5),low=ri(-2,1),high=low+ri(2,4);
   return functionGraph(number('На рисунке показан весь график функции. Из длины её области определения вычти длину множества значений.',
    d-(high-low),`Область определения [${integer(h)}; ${integer(h+d)}] имеет длину ${d}. Множество значений [${integer(low)}; ${integer(high)}] имеет длину ${high-low}.`),
    [[[h,low],[h+d,high]]]);
  },
  distinctOutputsInFiniteDomain:()=>{
   const h=ri(-2,2),d=ri(2,5),e=ri(1,4),k=ri(-3,3);
   return number(`Для функции y = ${shiftedTerm('|'+shiftedTerm('x',-h)+'|',k)} допустимы только целые x от ${integer(h-d)} до ${integer(h+e)} включительно. Сколько различных значений принимает функция?`,
    Math.max(d,e)+1,`Вершина при x = ${integer(h)} входит в область определения. Расстояния до неё перебираются от 0 до ${Math.max(d,e)}, и каждому расстоянию соответствует одно значение y.`);
  },
  commonValuesFromTwoTables:()=>{
   const a=ri(-4,0),b=ri(-2,3),gap=ri(1,3);
   const rows=Array.from({length:4},(_,i)=>[a+i,b+i,b+gap+i]);
   return valuesTable(number('Сколько чисел входят одновременно в множество значений f и множество значений g?',4-gap,
    `Значения f идут от ${integer(b)} до ${integer(b+3)}. Значения g — от ${integer(b+gap)} до ${integer(b+gap+3)}. Считаем общие числа.`),
    ['x','f(x)','g(x)'],rows);
  },
  denominatorAndRadicalBound:()=>{
   const a=ri(-3,2),b=a+ri(3,7),upper=b+ri(1,4);
   return number(`Сколько целых x от ${integer(a-2)} до ${upper} включительно входят в область определения функции y = ${frac('√('+shiftedTerm('x',-a)+')','√('+shiftedTerm('−x',b)+')')}?`,
    b-a,`Для числителя требуется x ≥ ${integer(a)}. Корень в знаменателе должен быть положительным, поэтому x &lt; ${b}. Считаем целые числа полуинтервала.`);
  },
  findIntegerInputsOfGivenOutputs:()=>{
   const a=ri(-3,0),b=a+ri(4,6),k=ri(-2,1),steps=ri(2,3);
   return functionGraph(number(`Показан весь график функции f. Сколько целых x из её области определения дают f(x) ≥ ${integer(k+steps)}?`,
    b-a-steps+1,`По графику заданный уровень достигается при x = ${integer(a+steps)}. Подходят целые x от этой абсциссы до ${integer(b)} включительно.`),
    [[[a,k],[b,k+b-a]]]);
  },
  decideDomainFromFinitePairs:()=>{
   const a=ri(-4,-1),b=ri(0,2),step=ri(1,3);
   const xs=[a,a+1,a+3,a+6],ys=[b,b,b+step,b+step];
   return valuesTable(choice('Таблица содержит все пары данной функции. Как записать её область определения?',
    `{${valueList(xs)}}`,[`{${valueList([b,b+step])}}`,`[${integer(a)}; ${integer(a+6)}]`,`{${valueList(xs.slice(0,-1))}}`],
    'Берём только аргументы, явно заданные в таблице. Промежуточные значения между ними из таблицы не следуют.'),
    ['x','y'],shuffleOptions(xs.map((x,i)=>[x,ys[i]])));
  },
  readMaximumWithCutoff:()=>{
   const a=ri(-4,-2),b=ri(2,4),k=ri(-3,0),d=ri(2,4);
   const values=[[a,k],[0,k+d],[b,k+1]],cut=ri(1,b-1);
   const maximum=rational((k+d)*b+(1-d)*cut,b);
   return functionGraph(number(`На рисунке показан график функции. Оставили только часть с x ≥ ${cut}. Какое наибольшее значение может принять функция на оставшейся части? Ответ при необходимости запиши дробью.`,
    maximum,
    `Справа от вершины график убывает от y = ${integer(k+d)} при x = 0 до y = ${integer(k+1)} при x = ${b}. На оставшемся участке максимум при x = ${cut}. На каждом шаге вправо y уменьшается на ${frac(d-1,b)}. Значит y = ${integer(k+d)} − ${cut} · ${frac(d-1,b)} = ${rationalRu(maximum)}.`),
    [values]);
  },
  rangeAfterSubtractingMinimum:()=>{
   const a=ri(-4,-2),b=ri(1,4),delta=ri(2,5),shift=ri(1,3);
   const rows=[[a,b],[a+1,b],[a+3,b+delta],[a+5,b-shift]];
   return valuesTable(number('Функцию задали таблицей. Каждое её значение уменьшили на минимальное значение из таблицы. Каково наибольшее новое значение?',delta+shift,
    `В исходной таблице минимум ${integer(b-shift)}, максимум ${b+delta}. Новое наибольшее значение есть их разность.`),
    ['x','y'],shuffleOptions(rows));
  }
 }
};

function inequalityInterval(task,left,right,leftClosed,rightClosed){
 return {...task,interval:{left,right,leftClosed,rightClosed}};
}

const inequalityMasters={
 linear_inequalities:{
  negativeFractionThreshold:()=>{
   const p=ri(2,5),q=ri(2,5),h=ri(-4,4),t=ri(1,5),c=q*t+p*h;
   return choice(`Реши неравенство ${frac(linear(-p,c),q)} ≥ ${t}. Какое условие на x равносильно исходному?`,
    `x ≤ ${integer(h)}`,[`x ≥ ${integer(h)}`,`x &lt; ${integer(h)}`,`x &gt; ${integer(h)}`],
    `Умножаем на положительное ${q} и переносим ${integer(c)} вправо. Получаем ${-p}x ≥ ${integer(-p*h)}. При делении на отрицательное число знак меняется.`);
  },
  differentDenominators:()=>{
   const a=ri(2,6),b=ri(2,4),h=ri(-3,4),c=ri(2,7),d=c+ri(1,4),t=d*(a+b)*h-c*b;
   return number(`Найди наименьшее целое решение неравенства ${frac(linear(a,0),c)} &gt; ${frac(linear(-d*b,t),c*d)}.`,
    h,`Домножаем обе части на ${c*d}. После переноса получаем ${d*(a+b)}x &gt; ${d*(a+b)*h-c*b}. Граница меньше ${integer(h)} и больше ${integer(h-1)}, поэтому первое целое справа от неё — ${integer(h)}.`);
  },
  bracketsBothSides:()=>{
   const p=ri(2,4),q=ri(2,5),a=ri(1,4),b=ri(1,4),h=ri(-2,4),c=(p+q)*h-p*a+q*b;
   return number(`Реши неравенство ${shiftedTerm('−'+p+'(x − '+a+')',c)} &lt; ${q}(x + ${b}). Найди наименьшее целое решение.`,
    h+1,`После раскрытия скобок и переноса получаем ${p+q}x &gt; ${(p+q)*h}, то есть x &gt; ${integer(h)}. Первое целое решение — ${integer(h+1)}.`);
  },
  variableCancelsAcrossSides:()=>{
   const p=ri(2,6),a=ri(1,5),b=ri(1,6),c=p*a+b+g8Pick([-2,-1,1,2]);
   const all=p*a+b<=c;
   const answer=all?'Все действительные числа':'Решений нет';
   return choice(`Найди множество решений неравенства ${p}(x + ${a}) + ${b} ≤ ${linear(p,c)}.`,answer,
    [all?'Решений нет':'Все действительные числа','Только x = 0','Только x > 0'],
    `Члены с x сокращаются. Остаётся ${p*a+b} ≤ ${c}. Это ${all?'верно при любом x':'ложно при любом x'}.`);
  },
  largestIntegerWithFractionalBoundary:()=>{
   const p=ri(3,6),h=ri(-5,3),d=ri(1,p-1),b=ri(-5,5),c=b-p*h-d;
   return number(`Найди наибольшее целое решение неравенства ${linear(-p,b)} &gt; ${integer(c)}.`,h,
    `Переносим ${integer(b)} и делим на ${integer(-p)}, меняя знак. Получаем x &lt; ${frac(p*h+d,p)} = ${integer(h)} + ${frac(d,p)}. Наибольшее целое решение — ${integer(h)}.`);
  },
  transformMarkedInterval:()=>{
   const a=ri(-5,-1),b=ri(1,5),k=ri(2,4),t=ri(-2,3);
   return inequalityInterval(number(`На прямой показаны допустимые x. Найди наибольшее значение выражения ${linear(-k,t)} на этом промежутке.`,t-k*a,
    `Выражение убывает при увеличении x. Максимум достигается в закрашенной левой точке x = ${integer(a)} и равен ${integer(t-k*a)}.`),
    rational(a),rational(b),true,false);
  },
  restoreConstantFromSolution:()=>{
   const p=ri(2,7),a=ri(-4,4),b=ri(2,12);
   return number(`Известно, что множество решений неравенства −${p}x + k ≥ ${b} равно (−∞; ${integer(a)}]. Найди k.`,b+p*a,
    `Правая граница ${integer(a)} удовлетворяет равенству −${p} · (${integer(a)}) + k = ${b}. Отсюда k = ${integer(b+p*a)}.`);
  },
  testExcludedEndpoint:()=>{
   const p=ri(2,6),h=ri(-4,4),b=ri(2,12),c=b-p*h;
   return choice(`Какое число не удовлетворяет неравенству ${linear(-p,b)} &lt; ${integer(c)}?`,integer(h),
    [integer(h+1),integer(h+3),integer(h+5)],
    `После деления на отрицательное число получаем x &gt; ${integer(h)}. Граница не включается из-за строгого знака.`);
  },
  budgetWithFixedFee:()=>{
   const fixed=10*ri(8,16),price=ri(18,35),total=ri(4,9),money=fixed+price*total+ri(1,price-1);
   return number(`За доставку платят ${fixed} руб. и ещё по ${price} руб. за каждую тетрадь. На покупку и доставку есть ${money} руб. Сколько тетрадей можно купить самое большее?`,total,
    `Если тетрадей x, то ${fixed} + ${price}x ≤ ${money}. После оплаты доставки остаётся ${money-fixed} руб. Делим на ${price} и берём целую часть.`);
  },
  countNegativeCoefficientSolutions:()=>{
   const p=ri(2,6),h=ri(-3,4),a=h-ri(2,6),b=h+ri(2,5),q=ri(-5,6),c=q-p*h;
   return number(`Сколько целых x от ${integer(a)} до ${integer(b)} включительно удовлетворяют ${linear(-p,q)} ≥ ${integer(c)}?`,h-a+1,
    `Неравенство равносильно x ≤ ${integer(h)}. Считаем целые от ${integer(a)} до ${integer(h)} включительно.`);
  }
 },
 equivalent_inequalities:{
  preserveAtNegativeDivision:()=>{
   const p=ri(2,7),h=ri(-5,4),b=ri(-6,7),c=b-p*h;
   return choice(`Выбери неравенство, равносильное ${linear(-p,b)} &gt; ${integer(c)}.`,`x &lt; ${integer(h)}`,
    [`x &gt; ${integer(h)}`,`x ≤ ${integer(h)}`,`x ≥ ${integer(h)}`],
    `Вычитаем одно и то же число и делим на −${p}. Направление меняется, строгий знак сохраняется.`);
  },
  diagnoseFalseEquivalenceByPoint:()=>{
   const h=ri(-5,3),a=ri(2,6),b=ri(1,5),c=b-a*h;
   return choice(`Ученик считает, что ${linear(-a,b)} ≥ ${integer(c)} равносильно x ≥ ${integer(h)}. Какое из чисел удовлетворяет второму условию, но не первому?`,
    integer(h+1),[integer(h),integer(h-1),integer(h-2)],
    `Исходное условие даёт x ≤ ${integer(h)}. Число ${integer(h+1)} подходит для второго, но не для первого.`);
  },
  retainFractionalBoundaryAndStrictness:()=>{
   const d=ri(2,7),a=ri(-4,4),r=ri(1,d-1),n=d*a+r;
   return choice(`Какое неравенство равносильно ${d}x ≤ ${integer(n)}?`,
    `x ≤ ${frac(n,d)}`,[`x &lt; ${frac(n,d)}`,`x ≤ ${integer(a)}`,`x ≥ ${frac(n,d)}`],
    `Делим на положительное ${d}. Граница остаётся точной дробью; округлять её до ${integer(a)} для действительных x нельзя.`);
  },
  guardAgainstUnknownMultiplierSign:()=>{
   const k=ri(1,6),a=ri(2,5),b=a+ri(1,4);
   return choice(`Из верного числового неравенства ${a} &lt; ${b} хотят получить ${a}(x − ${k}) &lt; ${b}(x − ${k}). При каком условии знак действительно сохраняется?`,
    `x &gt; ${k}`,[`x &lt; ${k}`,`x ≥ ${k}`,'При любом действительном x'],
    `Для сохранения строгого знака нужен положительный множитель x − ${k}. При x = ${k} получится равенство, слева от ${k} направление меняется.`);
  },
  avoidDividingOutEqualityPoint:()=>{
   const p=ri(1,7),a=ri(2,5);
   return number(`На отрезке [${p}; ${p+3}] разделили обе части ${a}(x − ${p}) ≤ (${a+1})(x − ${p}) на x − ${p}. Какое решение потеряли?`,p,
    `При x &gt; ${p} множитель положителен. При x = ${p} делить нельзя, но в исходном неравенстве обе части равны нулю.`);
  },
  equivalentOnlyAmongIntegers:()=>{
   const h=ri(-4,4),d=ri(2,6),a=ri(1,d-1),n=d*h+a;
   return choice(`Сравни множества решений условий ${d}x ≤ ${integer(n)} и x ≤ ${integer(h)}. Какое утверждение верно?`,
    'Они совпадают для целых x, а для действительных различаются',
    ['Они совпадают для всех действительных x','Множества целых решений различаются','Оба условия не имеют решений'],
    `Граница первого условия равна ${frac(n,d)} = ${integer(h)} + ${frac(a,d)}. Между границами нет целого числа, но есть действительные числа.`);
  },
  positiveFactorInBothDirections:()=>{
   const a=ri(2,6),h=ri(-4,4);
   return choice(`Множитель x² + ${a} положителен при любом действительном x. Какое условие равносильно (x² + ${a}) · (${linear(1,-h)}) ≤ 0?`,
    `x ≤ ${integer(h)}`,[`x ≥ ${integer(h)}`,`x &lt; ${integer(h)}`,'Решений нет'],
    `Деление на x² + ${a} допустимо при всех x. Получаем ${linear(1,-h)} ≤ 0 со включённой границей.`);
  },
  parameterFromSameBoundary:()=>{
   const a=ri(2,7),h=ri(-4,4),b=ri(1,7),k=b+a*h;
   return number(`Найди k, при котором ${linear(-a,b)} &lt; k и x &gt; ${integer(-h)} равносильны.`,
    k,`Первое условие имеет границу ${frac(b+' − k',a)}. Приравниваем её к ${integer(-h)}. Оба условия строгие и направлены вправо.`);
  },
  equivalentToMarkedRay:()=>{
   const h=ri(1,5),p=ri(2,6),b=ri(2,9),c=b-p*h;
   const lhs=linear(-p,b);
   return inequalityInterval(choice('Какое неравенство задаёт отмеченный на прямой луч?',
    `${lhs} &lt; ${integer(c)}`,[`${lhs} &gt; ${integer(c)}`,`${lhs} ≤ ${integer(c)}`,`${lhs} ≥ ${integer(c)}`],
    `Отмечено x &gt; ${h}. Умножаем на −${p} и прибавляем ${b}. Знак меняется, точка ${h} остаётся исключённой.`),
    rational(h),null,false,false);
  },
  explicitSameSolutionAfterBrackets:()=>{
   const a=ri(2,5),b=ri(1,6),h=ri(-4,4),sum=a*h+a*b;
   const right=`${a}(x + ${b}) ≥ ${integer(sum)}`;
   return choice(`Какое неравенство имеет то же множество решений, что и ${right}?`,
    `${linear(-a,0)} ≤ ${integer(-a*h)}`,[`${linear(-a,0)} ≥ ${integer(-a*h)}`,`${linear(a,0)} &gt; ${integer(a*h)}`,`${linear(a,0)} ≥ ${integer(sum)}`],
    `После раскрытия скобок получаем ${a}x ≥ ${integer(a*h)}. Для записи с отрицательным коэффициентом умножаем на −1 и меняем знак.`);
  }
 },
 linear_inequality_systems:{
  countFromOppositeSigns:()=>{
   const a=ri(-4,2),b=a+ri(3,7),p=ri(2,6),q=ri(2,5),c=ri(-5,5),d=ri(-5,7);
   return number(`Сколько целых x удовлетворяют одновременно ${linear(-p,c)} &lt; ${integer(c-p*a)} и ${linear(q,d)} ≤ ${integer(q*b+d)}?`,b-a,
    `Первое неравенство даёт x &gt; ${integer(a)}, второе — x ≤ ${integer(b)}. Подходят целые от ${integer(a+1)} до ${integer(b)} включительно.`);
  },
  intersectionIsSingleton:()=>{
   const h=ri(-4,5),p=ri(2,6),q=ri(2,5),c=ri(-5,5),d=ri(-4,6);
   return number(`Система ${linear(-p,c)} ≤ ${integer(c-p*h)} и ${linear(q,d)} ≤ ${integer(q*h+d)} имеет одно решение. Найди его.`,h,
    `Из первого неравенства получаем x ≥ ${integer(h)}, а из второго x ≤ ${integer(h)}. Обе границы включены, значит остаётся одна точка.`);
  },
  strictBoundaryLeavesNothing:()=>{
   const a=ri(-5,4),p=ri(2,6),q=ri(2,6),c=ri(1,6),d=ri(2,7);
   return choice(`Реши систему ${linear(p,c)} ≥ ${integer(p*a+c)} и ${linear(-q,d)} &gt; ${integer(d-q*a)}.`,'Решений нет',
    [`{${integer(a)}}`,`(−∞; ${integer(a)})`,`[${integer(a)}; +∞)`],
    `Первое неравенство требует x ≥ ${integer(a)}. Второе даёт x &lt; ${integer(a)}. Граничная точка не проходит строгое условие.`);
  },
  markedIntervalWithSecondBound:()=>{
   const a=ri(-5,-2),b=ri(3,7),h=ri(a+1,b-1),p=ri(2,5);
   return inequalityInterval(number(`Первое условие системы отмечено на прямой. Второе условие — ${linear(-p,0)} ≤ ${integer(-p*h)}. Сколько целых решений у системы?`,
    b-h,`Второе условие даёт x ≥ ${integer(h)}. Из отмеченного промежутка правая граница ${b} исключена. Получаем целые от ${integer(h)} до ${b-1}.`),
    rational(a),rational(b),true,false);
  },
  findExtremeIntegerSum:()=>{
   const a=ri(-6,-2),b=ri(2,7),p=ri(2,5),q=ri(2,5),d=ri(1,p-1),r=ri(1,q-1);
   return number(`Найди сумму наименьшего и наибольшего целых чисел, удовлетворяющих обоим условиям: ${p}x ≥ ${integer(p*a+d)} и ${q}x &lt; ${integer(q*b+r)}.`,a+1+b,
    `Левая граница лежит строго между ${integer(a)} и ${integer(a+1)}; правая — между ${b} и ${b+1}. Крайние целые равны ${integer(a+1)} и ${b}.`);
  },
  findRedundantCondition:()=>{
   const h=ri(-3,2),a=ri(2,4),b=ri(2,5),c=ri(2,4);
   const strongerA=`${a}x ≥ ${integer(a*h)}`,strongerB=`${b}x ≤ ${b*(h+4)}`,redundant=`${c}x ≥ ${integer(c*(h-2))}`;
   return choice(`В системе ${strongerA}, ${strongerB}, ${redundant}. Какое одно неравенство можно убрать, сохранив множество решений?`,
    redundant,[strongerA,strongerB,'Ни одно'],
    `Первые два дают отрезок [${integer(h)}; ${h+4}]. На нём третье условие x ≥ ${integer(h-2)} выполняется автоматически.`);
  },
  upperParameterByIntegerCount:()=>{
   const a=ri(-5,2),p=ri(2,5),count=ri(2,5);
   return number(`Система ${p}x ≥ ${integer(p*a)} и x &lt; k имеет ровно ${count} целых решений. Найди целое k.`,a+count,
    `Целые решения начинаются с ${integer(a)}. Последнее включённое равно ${integer(a+count-1)}. Следующее целое, уже исключённое, и есть k.`);
  },
  countFromDoubleAndSeparateBound:()=>{
   const a=ri(-4,1),h=a+ri(3,5),d=ri(1,3),p=ri(2,4);
   return number(`Сколько целых x выполняют двойное неравенство ${integer(a-2)} &lt; x ≤ ${h+d} и ещё условие ${linear(-p,0)} ≥ ${integer(-p*h)}?`,
    h-a+2,`Отдельное условие даёт x ≤ ${h}. Из двойного неравенства остаётся нижняя граница x &gt; ${integer(a-2)}. Считаем целые от ${integer(a-1)} до ${h}.`);
  },
  boxesMeetQuantityAndBudget:()=>{
   const size=ri(8,12),cost=10*ri(10,15),min=ri(3,5),max=min+ri(2,4),needed=size*min-ri(1,size-1),budget=cost*max+ri(1,cost-1);
   return number(`В коробке ${size} карандашей, коробка стоит ${cost} руб. Нужно купить не меньше ${needed} карандашей, бюджет ${budget} руб. Сколько разных количеств коробок подходит при покупке только целых коробок?`,
    max-min+1,`По количеству карандашей нужно не меньше ${min} коробок. По бюджету можно взять не больше ${max}. Считаем целые варианты с обеих границ.`);
  },
  lengthWithTwoFractionalBounds:()=>{
   const a=ri(-3,1),b=a+ri(2,6),p=ri(2,5),q=ri(2,6);
   const lower=rational(p*a+1,p),upper=rational(q*b-1,q),length=rational(p*q*(b-a)-p-q,p*q);
   return number(`Найди длину промежутка решений системы ${p}x ≥ ${integer(p*a+1)} и ${linear(-q,0)} &gt; ${integer(1-q*b)}. Ответ можно записать дробью.`,length,
    `После деления получаем x ≥ ${rationalRu(lower)} и x &lt; ${rationalRu(upper)}. Вычитаем нижнюю границу из верхней: ${rationalRu(length)}.`);
  }
 },
 inequality_proofs:{
  exactUpperBoundBySquare:()=>{
   const a=ri(2,7),p=ri(2,5),d=ri(1,8),b=p*a*a+d;
   return number(`Какую наименьшую верхнюю границу имеет выражение ${linear(2*p*a,d)} − ${p}x² при всех действительных x?`,b,
    `Выделяем квадрат: ${b} − ${p}(x − ${a})². Квадрат неотрицателен, поэтому выше ${b} подняться нельзя. При x = ${a} это значение достигается.`);
  },
  squaredExpressionEqualityCount:()=>{
   const a=ri(2,7),b=a*a,k=ri(2,5);
   return number(`Неравенство (x² + ${b})² ≥ ${4*b}x² верно при всех x. Приравняй части и найди сумму значений ${k}x² во всех случаях равенства.`,2*b*k,
    `Разность частей равна (x² − ${b})². Равенство при x = ±${a}. Квадрат каждого равен ${b}; после сложения умножаем на ${k}.`);
  },
  counterexampleAtNonzeroCenter:()=>{
   const a=ri(2,8),k=ri(1,4);
   return choice(`Какое число опровергает утверждение «(x − ${a})² + ${k} ≥ ${k+1} для всех действительных x»?`,String(a),
    [String(a-1),String(a+1),String(a+3)],
    `При x = ${a} квадрат обращается в нуль, левая часть равна ${k}. При x = ${a-1} и x = ${a+1} получается равенство, так что эти числа не опровергают утверждение.`);
  },
  proveViaNonnegativeProduct:()=>{
   const a=ri(-4,1),b=a+ri(3,7),from=ri(a+1,b-1);
   const f=linear(1,-a),g=linear(-1,b);
   return number(`Если x ∈ [${integer(a)}; ${b}], верно (${f})(${g}) ≥ 0. Какое число из отрезка [${integer(from)}; ${b+1}] обращает это произведение в нуль?`,b,
    `На [${integer(a)}; ${b}] оба множителя неотрицательны. Равенство возможно в точках ${integer(a)} и ${b}, но из них в заданный отрезок попадает только ${b}.`);
  },
  constrainedProductEquality:()=>{
   const a=ri(2,6),b=ri(2,8),s=a+b;
   return number(`Пусть x и y — положительные числа, их сумма равна ${2*s}. Найди наибольшее возможное произведение xy.`,s*s,
    `Из (x − y)² ≥ 0 следует (x + y)² ≥ 4xy. Подставляем сумму: xy ≤ ${s*s}. Граница достигается при x = y = ${s}.`);
  },
  testWhetherDomainIsEnough:()=>{
   const a=ri(2,6),b=ri(a+1,a+4);
   return choice(`Дано x ≤ ${a}. Какое дополнительное условие обязательно делает вывод x² ≤ ${a*a} верным?`,
    `x ≥ −${a}`,[`x ≥ −${b}`,`x ≤ −${a}`,'Достаточно исходного условия'],
    `Для x² ≤ ${a*a} модуль x не больше ${a}. Кроме верхней границы x ≤ ${a}, нужна нижняя x ≥ −${a}.`);
  },
  combineNonnegativeTerms:()=>{
   const a=ri(2,7),p=ri(2,5),q=ri(2,6),r=ri(2,7);
   return number(`Найди наименьшее значение ${p}(x − ${a})² + ${q}(y + ${a})² + ${r} при любых действительных x и y.`,r,
    `Оба слагаемых с квадратами неотрицательны. При x = ${a} и y = −${a} оба одновременно равны нулю. Остаётся ${r}.`);
  },
  weightedReciprocalLowerBound:()=>{
   const p=ri(2,4),a=ri(2,6),r=ri(1,6);
   return number(`При x &gt; 0 найди точную нижнюю границу выражения ${p}x + ${frac(p*a*a,'x')} + ${r}.`,2*p*a+r,
    `Вычитаем ${2*p*a+r} и приводим к общему знаменателю: получаем ${frac(p+'(x − '+a+')²','x')} ≥ 0. При x = ${a} граница достигается.`);
  },
  deriveBoundFromTwoVariables:()=>{
   const a=ri(2,7),b=ri(1,5),p=ri(2,4);
   return number(`Известно x ≥ ${a} и y ≤ −${b}. Найди точную нижнюю границу выражения ${p}x − (${p+1})y.`,
    p*a+(p+1)*b,`После умножения второго неравенства на −${p+1} получаем −${p+1}y ≥ ${(p+1)*b}. Складываем с ${p}x ≥ ${p*a}. Равенство выходит при x = ${a} и y = −${b}.`);
  },
  compareCorrectProofLines:()=>{
   const a=ri(2,8),b=ri(1,6),p=ri(2,5);
   const expr=`${p}x² − ${2*p*a}x + ${p*a*a+b}`;
   return choice(`Какой записью можно обосновать, что ${expr} ≥ ${b} при всех x?`,
    `${p}(x − ${a})² + ${b}`,[`${p}(x + ${a})² + ${b}`,`${p}(x − ${a})² − ${b}`,`(x − ${a})² + ${b}`],
    `Выделяем полный квадрат. Он умножен на положительное число ${p}. Прибавление ${b} даёт нижнюю границу ${b}.`);
  }
 },

 set_union_intersection:{
  recoverIntersectionFromTotal:()=>{
   const shared=ri(2,7),onlyA=ri(4,9),onlyB=ri(4,9);
   return number(`В кружке робототехники ${shared+onlyA} учеников, в кружке моделирования ${shared+onlyB}. Хотя бы один из них посещают ${shared+onlyA+onlyB} учеников. Сколько учеников ходят в оба кружка?`,
    shared,`Складывая численности кружков, дважды учитываем тех, кто ходит в оба. Вычитаем число учеников, которые ходят хотя бы в один.`);
  },
  countOnlyOneSet:()=>{
   const common=ri(2,7),a=common+ri(4,8),b=common+ri(3,7);
   return number(`В A ${a} элементов, в B ${b}, в пересечении ${common}. Сколько элементов принадлежат ровно одному из множеств?`,
    a+b-2*common,`Только в A находятся ${a-common} элементов, только в B — ${b-common}. Складываем эти два числа.`);
  },
  distributeBeforeCounting:()=>{
   const a=ri(2,9),b=g8Pick([1,3,4]);
   const sets=[[a,a+1,a+2,a+5],[a+1,a+3,a+5,a+6],[a-1,a+1,a+3,a+7,a+5+b]];
   const [A,B,C]=sets.map(values=>'{'+valueList(values)+'}');
   return number(`Даны A = ${A}, B = ${B}, C = ${C}. Сколько элементов в (A ∪ B) ∩ C?`,
    sets[2].filter(x=>sets[0].includes(x)||sets[1].includes(x)).length,
    `Оставляем в C те числа, которые есть хотя бы в одном из A или B. Получаем ${valueList(sets[2].filter(x=>sets[0].includes(x)||sets[1].includes(x)))}.`);
  },
  unionOfPairedIntersections:()=>{
   const a=ri(2,8),b=a+ri(7,12);
   const first=[a,a+2,a+4],middle=[a,a+1,a+2,a+4,b],last=[a+2,a+4,b,b+1];
   return number(`Пусть A = {${valueList(first)}}, B = {${valueList(middle)}}, C = {${valueList(last)}}. Найди сумму элементов множества (A ∩ B) ∪ (B ∩ C).`,
    a+(a+2)+(a+4)+b,`Первое пересечение даёт ${valueList(first)}, второе — ${valueList([a+2,a+4,b])}. При объединении повторяющиеся числа учитываем по одному разу.`);
  },
  neitherOfTheGroups:()=>{
   const season=ri(26,38),a=ri(11,15),b=ri(10,14),c=Math.max(4,a+b-season+1)+ri(0,3);
   return number(`В классе ${season} учеников. Из них ${a} занимаются плаванием, ${b} ходят на танцы, ${c} занимаются и тем и другим. Сколько учеников не занимаются ни плаванием, ни танцами?`,
    season-a-b+c,`Хотя бы одним из занятий занимаются ${a} + ${b} − ${c} = ${a+b-c} учеников. Вычитаем их число из общего.`);
  },
  multiplesUnderTwoConditions:()=>{
   const lo=ri(3,10),hi=lo+ri(11,18);
   const count=Math.floor(hi/2)-Math.floor((lo-1)/2)+Math.floor(hi/3)-Math.floor((lo-1)/3)-Math.floor(hi/6)+Math.floor((lo-1)/6);
   return number(`A состоит из чётных целых от ${lo} до ${hi} включительно, B — из целых на том же отрезке, кратных трём. Сколько элементов в A ∪ B?`,
    count,'Складываем количества чётных и кратных трём. Вычитаем числа, кратные шести, так как они вошли в оба подсчёта.');
  },
  commonResultsOfThreeGroups:()=>{
   const a=ri(3,7),ab=ri(1,4),bc=ri(1,4),ca=ri(1,4),abc=ri(2,5);
   const union=3*a+ab+bc+ca+abc;
   return number(`В каждом из трёх множеств ровно ${a} элементов, которые принадлежат только этому множеству. Ровно двум множествам принадлежат ${ab+bc+ca} элементов. Всего в объединении ${union} элементов. Сколько элементов в пересечении всех трёх?`,
    abc,`Из ${union} вычитаем ${3*a} элементов, принадлежащих только одному множеству, и ${ab+bc+ca} элементов, принадлежащих ровно двум.`);
  },
  counterexampleToUnionClaim:()=>{
   const x=ri(2,8),a=x+1,b=x+4,c=b+2;
   return choice(`Даны A = {${x}, ${a}, ${b}}, B = {${a}, ${b}, ${c}}. Какое число опровергает утверждение «каждый элемент A ∪ B входит в B»?`,
    String(x),[String(a),String(b),String(c)],`Число ${x} входит в A, значит входит в объединение. В B этого числа нет.`);
  },
  inferOneCardinality:()=>{
   const a=ri(9,16),common=ri(3,7),onlyB=ri(4,9);
   return number(`Во множестве A ${a} элементов, а в A ∪ B их ${a+onlyB}. В пересечении A ∩ B ${common} элементов. Сколько элементов в B?`,
    onlyB+common,`В объединении на ${onlyB} элементов больше, чем в A. Это элементы, принадлежащие только B. Добавляем ${common} общих элементов.`);
  },
  findSetForNeitherCondition:()=>{
   const a=ri(2,6),u=[a,a+1,a+2,a+3,a+4,a+5];
   return choice(`В U = {${valueList(u)}} заданы A = {${a}, ${a+2}, ${a+4}} и B = {${a+1}, ${a+2}}. Выбери элементы U, которые не входят ни в A, ни в B.`,
    `{${a+3}, ${a+5}}`,[`{${a+2}}`,`{${a}, ${a+1}, ${a+2}, ${a+4}}`,`{${a+3}, ${a+4}, ${a+5}}`],
    `В A ∪ B находятся ${valueList([a,a+1,a+2,a+4])}. Исключаем их из U.`);
  }
 },
 number_intervals:{
  extremeSumWithFractionalEndpoints:()=>{
   const a=ri(-7,-2),b=ri(2,7);
   return number(`Найди сумму наименьшего и наибольшего целого числа в пересечении (${integer(a)},5; ${b+1}] и [${integer(a-2)}; ${b},5).`,
    a+b,`Пересечение начинается правее ${integer(a)},5 и заканчивается перед ${b},5. Крайние целые — ${integer(a)} и ${b}.`);
  },
  missingPointBetweenTwoIntervals:()=>{
   const a=ri(-5,-2),h=ri(a+1,3),b=h+ri(2,5);
   return number(`Какое единственное число из отрезка [${integer(a)}; ${b}] не входит в объединение [${integer(a)}; ${integer(h)}) ∪ (${integer(h)}; ${b}]?`,
    h,`Внутри отрезка обе части покрывают все числа, кроме ${integer(h)}. Обе скобки при этой границе круглые.`);
  },
  reflectedAndShiftedMarkedInterval:()=>{
   const a=ri(-5,-1),b=ri(2,6),c=ri(1,3);
   const reflected=`(${integer(c-b)}; ${c-a}]`;
   return inequalityInterval(choice(`x принадлежит отмеченному промежутку. Какому промежутку принадлежит число ${linear(-1,c)}?`,reflected,
    [`[${integer(c-b)}; ${c-a})`,`(${integer(c-b)}; ${c-a})`,`[${integer(c-b)}; ${c-a}]`],
    `Меняем знак x и отражаем промежуток: открытая граница переходит в левый конец, закрытая — в правый. Затем прибавляем ${c} к обеим границам.`),
    rational(a),rational(b),true,false);
  },
  markedIntervalWithStrictRay:()=>{
   const a=ri(-6,-2),b=ri(3,7),h=ri(a+1,b-2);
   return inequalityInterval(number(`Сколько целых чисел принадлежат отмеченному промежутку и одновременно больше ${integer(h)}?`,
    b-h,`Из отмеченного промежутка оставляем целые числа от ${integer(h+1)} до закрытой границы ${b} включительно.`),
    rational(a),rational(b),false,true);
  },
  overlappingUnionOuterEndpoints:()=>{
   const a=ri(-6,-2),b=a+ri(2,4),c=b+ri(2,4),d=c+ri(2,4);
   const answer=`(${integer(a)}; ${d}]`;
   return choice(`Запиши объединение промежутков (${integer(a)}; ${integer(c)}) и [${integer(b)}; ${d}].`,answer,
    [`[${integer(a)}; ${d}]`,`(${integer(a)}; ${d})`,`[${integer(b)}; ${integer(c)})`],
    `Промежутки перекрываются. Левый внешний конец не входит в объединение, правый входит.`);
  },
  countIntegersInIntervalDifference:()=>{
   const a=ri(-6,-2),c=a+ri(2,4),d=c+ri(2,4),b=d+ri(2,5);
   return number(`Сколько целых чисел из [${integer(a)}; ${b}) останется, если удалить все числа из (${integer(c)}; ${integer(d)}]?`,
    c-a+b-d,`Остаются отрезок [${integer(a)}; ${integer(c)}] и промежуток (${integer(d)}; ${b}). Складываем количества целых в этих двух частях.`);
  },
  recoverOpenUpperEndpoint:()=>{
   const a=ri(-5,2),count=ri(3,8);
   return number(`Промежуток [${integer(a)}; b) содержит ровно ${count} целых чисел. Найди b, если b — целое.`,
    a+count,`Первое целое равно ${integer(a)}, последнее — ${integer(a+count-1)}. Правая граница исключена и идёт сразу за последним целым.`);
  },
  reflectAfterNegativeScale:()=>{
   const a=ri(-5,-1),b=ri(2,6),k=ri(2,4);
   return choice(`Известно, что x ∈ (${integer(a)}; ${b}]. В какой промежуток попадает y = ${linear(-k,0)}?`,
    `[${integer(-k*b)}; ${-k*a})`,[`(${integer(-k*b)}; ${-k*a}]`,`(${integer(k*a)}; ${k*b})`,`[${integer(-k*b)}; ${-k*a}]`],
    `Умножаем обе границы на −${k}, поэтому их порядок меняется. Включённая граница ${b} станет левой границей ${integer(-k*b)}.`);
  },
  sumAllIntegersAfterIntersection:()=>{
   const a=ri(-4,-2),b=ri(2,6),lo=a+1,hi=b-1;
   return number(`Найди сумму всех целых чисел, общих для (${integer(a)}; ${b+2}] и [${integer(a-2)}; ${b}).`,
    (lo+hi)*(hi-lo+1)/2,`Общий промежуток — (${integer(a)}; ${b}). Подходящие целые начинаются с ${integer(lo)} и заканчиваются ${hi}. Суммируем их, попарно складывая числа с концов списка.`);
  },
  pointFromBoundedAndUnboundedIntervals:()=>{
   const a=ri(-5,-2),b=ri(2,6),c=ri(a+1,b-1);
   return choice(`Из [${integer(a)}; ${b}] исключили все числа из (−∞; ${integer(c)}) и (${integer(c)}; +∞). Что осталось?`,
    `{${integer(c)}}`,['Пустое множество',`[${integer(a)}; ${integer(c)}]`,`[${integer(c)}; ${b}]`],
    `Оба исключаемых луча имеют открытую границу в точке ${integer(c)}. Они убирают все остальные числа заданного отрезка.`);
  }
 }
};

function gridPolygon(task,...contours){
 const figure=functionGraph(task,contours.map(points=>[...points,points[0]]));
 const graphCaption='Контур многоугольника на координатной сетке';
 figure.graphCaption=graphCaption;
 figure.graph.caption=graphCaption;
 figure.graph.series.forEach((path,i)=>{path.label=contours.length===1?'Контур фигуры':i===0?'Внешний контур':'Контур выреза';});
 return figure;
}
function gridRectangle(x,y,w,h){
 return [[x,y],[x+w,y],[x+w,y+h],[x,y+h]];
}
function medianFigure(task,A,B,C,includeExtension=true){
 const M=[(B[0]+C[0])/2,(B[1]+C[1])/2],D=[2*M[0]-A[0],2*M[1]-A[1]];
 const curves=[[A,B,C,A],[A,includeExtension?D:M]], marks=[[...A,'A'],[...B,'B'],[...C,'C'],[...M,'M']];
 if(includeExtension){
  curves.push([B,D,C]);
  marks.push([...D,'D']);
 }
 const figure=functionGraph(task,curves,marks);
 figure.graphCaption='Треугольник ABC и построение на медиане AM';
 figure.graph.caption=figure.graphCaption;
 figure.graph.series.forEach((path,i)=>{path.label=['Треугольник ABC','Медиана AM','Дополнительные отрезки'][i];});
 return figure;
}

const geometryMasters={
 polygon_grid_area:{
  scaleLShapedRegion:()=>{
   const w=ri(5,7),h=ri(4,6),a=ri(2,3),b=ri(2,3),cell=ri(2,4),x=-3,y=-2;
   const area=w*h-a*b;
   return gridPolygon(number(`На сетке показана Г-образная фигура. Сторона клетки ${cell} см. Найди площадь фигуры в см².`,area*cell**2,
    `Внешний прямоугольник содержит ${w} · ${h} клеток, вырез — ${a} · ${b}. Остаётся ${area} клеток. Площадь клетки ${cell**2} см², значит площадь фигуры ${area*cell**2} см².`,'см²'),
    [[x,y],[x+w,y],[x+w,y+h-b],[x+w-a,y+h-b],[x+w-a,y+h],[x,y+h]]);
  },
  areaWithInteriorWindow:()=>{
   const w=ri(6,8),h=ri(5,7),a=ri(2,4),b=ri(2,3),x=-4,y=-3;
   return gridPolygon(number('На рисунке внешний прямоугольник обозначает всю деталь, внутренний — вырез. Найди площадь оставшейся детали, если площадь клетки равна 1 см².',
    w*h-a*b,`Считываем стороны внешнего прямоугольника ${w} и ${h}, выреза — ${a} и ${b}. Разность площадей равна ${w*h} − ${a*b} = ${w*h-a*b} см².`,'см²'),
    gridRectangle(x,y,w,h),gridRectangle(x+1,y+1,a,b));
  },
  twoDifferentCornerCuts:()=>{
   const w=ri(6,8),h=ri(5,7),a=ri(2,3),b=ri(2,4),c=ri(1,2),d=ri(2,4),x=-4,y=-3;
   const value=rational(2*w*h-a*b-c*d,2);
   return gridPolygon(number('От прямоугольника отрезали два угла. По контуру на сетке найди площадь оставшегося многоугольника. Площадь клетки равна 1 см².',value,
    `Из площади прямоугольника ${w*h} см² вычитаем площади прямоугольных треугольников: ${frac(a+' · '+b,2)} и ${frac(c+' · '+d,2)} см².`,'см²'),
    [[x+a,y],[x+w,y],[x+w,y+h-d],[x+w-c,y+h],[x,y+h],[x,y+b]]);
  },
  trapezoidByMeasuredCellSize:()=>{
   const b=ri(5,8),t=b-ri(2,3),h=ri(2,5),cell=ri(2,3),x=-4,y=-2;
   const value=rational((b+t)*h*cell*cell,2);
   return gridPolygon(number(`Сторона клетки ${cell} см. Найди площадь трапеции на рисунке в см².`,value,
    `Основания занимают ${b} и ${t} клеток, высота — ${h} клеток. Площадь в клетках равна ${frac('('+b+' + '+t+') · '+h,2)}. Умножаем на площадь клетки ${cell*cell} см².`,'см²'),
    [[x,y],[x+b,y],[x+1+t,y+h],[x+1,y+h]]);
  },
  cellLengthFromWholeArea:()=>{
   const base=ri(4,7),h=2*ri(2,3),cell=ri(2,5),x=-3,y=-3,cells=base*h/2;
   return gridPolygon(number(`Площадь треугольника на рисунке ${cells*cell**2} см². Найди длину стороны клетки.`,cell,
    `Основание треугольника занимает ${base} клеток, высота — ${h}. Площадь треугольника равна ${cells} площадям клетки. Одна клетка имеет площадь ${cell**2} см² и сторону ${cell} см.`,'см'),
    [[x,y],[x+base,y],[x+2,y+h]]);
  },
  tiltedParallelogramBySurroundingRectangle:()=>{
   const a=ri(3,5),b=ri(3,5),x=-3,y=-3,value=a*b-1;
   return gridPolygon(number('Найди площадь параллелограмма на сетке, если площадь клетки равна 1 см².',value,
    `Описываем фигуру прямоугольником ${a+1} × ${b+1}. Разность площадей складывается из двух прямоугольных треугольников с катетами ${a} и 1, двух с катетами ${b} и 1 и двух угловых клеток. Площадь фигуры — ${(a+1)*(b+1)} − ${a} − ${b} − 2 = ${value} см².`,'см²'),
    [[x,y],[x+a,y+1],[x+a+1,y+b+1],[x+1,y+b]]);
  },
  cutTriangleAlongTopSide:()=>{
   const w=ri(6,8),h=ri(4,6),a=ri(2,4),d=ri(2,h-1),x=-4,y=-3;
   const removed=rational(a*d,2);
   return gridPolygon(number('Верхняя сторона прямоугольника имела треугольный вырез. По контуру оставшейся детали найди площадь выреза. Площадь клетки равна 1 см².',
    removed,`Основание выреза занимает ${a} клеток, высота — ${d}. Умножаем основание на высоту и делим на 2.`,'см²'),
    [[x,y],[x+w,y],[x+w,y+h],[x+1+a,y+h],[x+2,y+h-d],[x+1,y+h],[x,y+h]]);
  },
  twoRegionsWithSameBase:()=>{
   const b=ri(4,7),h=ri(2,4),g=ri(2,4),x=-3,y=0;
   return gridPolygon(number('Показан четырёхугольник, у которого горизонтальная диагональ лежит на оси Ox. Найди его площадь. Площадь клетки равна 1 см².',
    rational(b*(h+g),2),`Диагональ длиной ${b} клеток делит фигуру на два треугольника с высотами ${h} и ${g}. Складываем ${frac(b+' · '+h,2)} и ${frac(b+' · '+g,2)} см².`,'см²'),
    [[x,y],[x+2,y-h],[x+b,y],[x+1,y+g]]);
  },
  areaAfterVerticalStretch:()=>{
   const w=ri(4,6),h=ri(3,5),a=ri(1,3),b=ri(1,2),factor=ri(2,4),x=-3,y=-2,area=w*h-a*b;
   return gridPolygon(number(`В показанной фигуре все вертикальные размеры увеличили в ${factor} раза, а горизонтальные сохранили. Какова новая площадь в квадратных клетках?`,
    area*factor,`Исходная площадь ${w} · ${h} − ${a} · ${b} = ${area} квадратных клеток. После растяжения высота каждой из частей увеличивается в ${factor} раза, поэтому площадь равна ${area*factor}.`),
    [[x,y],[x+w,y],[x+w,y+h-b],[x+w-a,y+h-b],[x+w-a,y+h],[x,y+h]]);
  },
  areaRatioCutShapeToWhole:()=>{
   const w=ri(5,7),h=ri(4,6),a=ri(2,3),b=ri(2,3),x=-3,y=-2;
   return gridPolygon(number('Какую долю площади внешнего прямоугольника занимает прямоугольный вырез? Ответ запиши дробью.',
    rational(a*b,w*h),`Вырез имеет площадь ${a*b} квадратных клеток, весь прямоугольник до вырезания — ${w*h}. Делим площадь выреза на площадь целого.`),
    gridRectangle(x,y,w,h),gridRectangle(x+1,y+1,a,b));
  }
 },
 median_doubling_method:{
  perimeterOfConstructedTriangle:()=>{
   const a=ri(5,10),b=a+ri(-2,4),m=ri(3,Math.min(6,Math.floor((a+b-1)/2)));
   return number(`В треугольнике ABC медиану AM продолжили за M до точки D так, что AM = MD. AB = ${a} см, AC = ${b} см, AM = ${m} см. Найди периметр треугольника ABD.`,
    a+b+2*m,`Диагонали AD и BC делятся пополам, поэтому ABDC — параллелограмм и BD = AC = ${b} см. Кроме того, AD = 2AM = ${2*m} см. Складываем стороны ABD.`,'см');
  },
  recoverOriginalSide:()=>{
   const a=ri(5,10),b=a+ri(-2,4),m=ri(3,Math.min(6,Math.floor((a+b-1)/2)));
   return number(`Медиану AM треугольника ABC удвоили до AD, причём M — середина AD. Периметр ABD равен ${a+b+2*m} см, AB = ${a} см и AM = ${m} см. Найди AC.`,
    b,`В параллелограмме ABDC стороны AC и BD равны. Вычитаем из периметра ABD стороны AB = ${a} см и AD = ${2*m} см. Получаем BD = AC = ${b} см.`,'см');
  },
  angleAcrossParallelSides:()=>{
   const scale=ri(2,3),h=ri(-1,1),right=g8Pick([true,false]);
   const A=right?[h-scale,0]:[h-scale,-scale],B=[h+scale,-scale],C=[h-scale,scale];
   const angle=right?90:45;
   return medianFigure(number(`Удвоили медиану AM. Какова величина угла BDA, если ∠CAM = ${angle}°?`,angle,
    'По построению ABDC — параллелограмм. Луч DB противоположно направлен лучу AC, а луч DA — лучу AM. Поворот обоих лучей на 180° сохраняет величину угла.','°'),
    A,B,C);
  },
  upperIntegerMedianByTriangleInequality:()=>{
   const a=ri(6,12),b=ri(5,11),largest=Math.floor((a+b-1)/2);
   return number(`Стороны AB и AC треугольника равны ${a} и ${b} см. Найди наибольшую возможную целую длину медианы AM в сантиметрах.`,
    largest,`После удвоения медианы у треугольника ABD стороны ${a}, ${b} и 2AM. Значит |${a} − ${b}| &lt; 2AM &lt; ${a+b}. Наибольшая целая длина под верхней границей — ${largest} см.`,'см');
  },
  findEndpointAfterExtension:()=>{
   const h=ri(-2,-1),a=ri(2,4),u=ri(1,2),v=ri(2,3);
   const A=[h,-2],B=[h+2*a,-2],C=[h+2*u,-2+2*v],m=h+a+u,answer=2*m-h;
   return medianFigure(number('На рисунке показана медиана AM. Её продолжили за M до D, где MD = AM. Найди абсциссу D.',
    answer,`По рисунку абсциссы A и M равны ${integer(h)} и ${m}. Так как M — середина AD, абсцисса D равна 2 · ${m} − (${integer(h)}) = ${answer}.`),
    A,B,C,false);
  },
  areaFromHeightOfNewTriangle:()=>{
   const a=ri(2,4),h=ri(2,3),offset=ri(-1,1),A=[-3,-2],B=[2*a-3,-2],C=[2*offset-3,2*h-2];
   return medianFigure(number(`Медиану AM удвоили до AD. Длина AB равна ${2*a} см, расстояние от D до прямой AB равно ${2*h} см. Найди площадь ABC.`,2*a*h,
    `Поскольку ABDC — параллелограмм, диагонали AD и BC делят его на равновеликие треугольники. Значит площади ABC и ABD одинаковы. Площадь ABD равна ${frac(2*a+' · '+2*h,2)} = ${2*a*h} см².`,'см²'),A,B,C);
  },
  fourEqualRegionsAfterDoubling:()=>{
   const a=ri(2,4),h=ri(2,3),offset=ri(-1,1),A=[-3,-2],B=[2*a-3,-2],C=[2*offset-3,2*h-2];
   return medianFigure(number(`Удвоили медиану AM. Площадь треугольника ABM равна ${a*h} см². Найди площадь четырёхугольника ABDC.`,4*a*h,
    `В параллелограмме ABDC диагонали пересекаются в серединах. Четыре треугольника вокруг M равновелики. Умножаем площадь одного на 4.`,'см²'),A,B,C);
  },
  recoverSideFromTwoPerimeters:()=>{
   const a=ri(5,10),b=a+ri(1,4),c=ri(5,a+b-2);
   return number(`Медиану AM удвоили до AD. Периметр ABC равен ${a+b+c} см, а периметр ABDC равен ${2*(a+b)} см. Найди BC.`,c,
    `Четырёхугольник ABDC — параллелограмм. Половина его периметра равна AB + AC, то есть ${a+b} см. Вычитаем эту сумму из периметра ABC.`,'см');
  },
  diagnoseMissingCondition:()=>{
   const area=ri(2,4),a=ri(2,3),b=ri(2,3),A=[-area,-2],B=[2*a-area,-2],C=[-area,2*b-2];
   return medianFigure(choice('Медиану AM удвоили до AD. Какой факт позволяет сразу доказать, что ABDC — параллелограмм?',
    'AD и BC делятся точкой M пополам',
    ['Длины AD и BC обязательно равны','Стороны AB и BD всегда равны','AD и BC всегда перпендикулярны'],
    'В четырёхугольнике ABDC отрезки AD и BC — диагонали. Они пересекаются в своих серединах, а это признак параллелограмма.'),A,B,C);
  },
  doubledLengthFromSumOfTwoPerimeters:()=>{
   const a=ri(5,10),b=a+ri(-2,4),m=ri(3,Math.min(6,Math.floor((a+b-1)/2))),perimeter=2*(a+b);
   return number(`Медиану AM удвоили до AD. Сумма периметров ABD и ACD равна ${perimeter+4*m} см, периметр ABDC равен ${perimeter} см. Найди AM.`,m,
    `В сумме периметров треугольников все стороны четырёхугольника учитываются по одному разу, а диагональ AD — дважды. Вычитаем периметр четырёхугольника и делим остаток на 4, поскольку AD = 2AM.`,'см');
  }
 }
};

function masterVenn(task,aOnly,both,bOnly,outside){
 return {...task,venn:{aOnly,both,bOnly,outside}};
}

function finiteSet(values){
 return '{'+values.map(value=>typeof value==='number'?integer(value):value).join(', ')+'}';
}
